#define Rot(a)  mat2(cos(a - vec4(0,11,33,0)))
#define antialiasing(n) n/min(iResolution.y,iResolution.x)
#define S(d) 1.-smoothstep(-1.2,1.2, (d)*iResolution.y )
#define B(p,s) max(abs(p).x-s.x,abs(p).y-s.y)
#define deg45 .707
#define R45(p) (( p + vec2(p.y,-p.x) ) *deg45)
#define Tri(p,s) max(R45(p).x,max(R45(p).y,B(p,s)))

float animateTri(vec2 p){
    vec2 prevP = p;
    p.y-=iTime*0.05;
    p.y+=0.019;
    p.y = mod(p.y,0.04)-0.02;
    float d = Tri(p,vec2(0.02));
    d = max(abs(prevP.y)-0.02,d);
    return d;
}

float char0(vec2 p){
    vec2 prevP  = p;
    float d = B(p,vec2(0.13,0.17));
    float d2 = B(p,vec2(0.06,0.1));
    d = max(-d2,d);
    float a = radians(-45.);
    p.y-=0.25;
    d = max(-dot(p,vec2(cos(a),sin(a))),d);
    p = prevP;
    p.y+=0.25;
    d = max(dot(p,vec2(cos(a),sin(a))),d);
    return d;
}

float char2(vec2 p){
    vec2 prevP  = p;
    p.y = abs(p.y)-0.135;
    float d = B(p,vec2(0.13,0.035));
    p = prevP;
    p*=Rot(radians(45.));
    float d2 = B(p,vec2(0.035,0.22));
    d = min(d,d2);
    p = prevP;
    d = max(abs(p.y)-0.17,d);
    d = max(abs(p.x)-0.13,d);

    p.x+=0.13;
    p.y-=0.105;
    p*=Rot(radians(-45.));
    d2 = Tri(p,vec2(0.05));
    d = min(d,d2);

    p = prevP;
    p.x-=0.13;
    p.y+=0.105;
    p*=Rot(radians(135.));
    d2 = Tri(p,vec2(0.05));
    d = min(d,d2);

    return d;
}

float char5(vec2 p){
    vec2 prevP  = p;
    p.y = abs(p.y)-0.135;
    float d = B(p,vec2(0.13,0.035));

    p = prevP;
    float d2 = B(p,vec2(0.13,0.035));
    d = min(d,d2);

    p.x+=0.095;
    p.y-=0.101;
    d2 = B(p,vec2(0.035,0.07));
    d = min(d,d2);

    p = prevP;
    p.x-=0.095;
    p.y+=0.101;
    d2 = B(p,vec2(0.035,0.07));
    d = min(d,d2);

    p = prevP;
    p.y+=0.25;
    float a = radians(-45.);
    d = max(dot(p,vec2(cos(a),sin(a))),d);    
    p = prevP;
    p.y-=0.25;
    d = max(-dot(p,vec2(cos(a),sin(a))),d);

    p = prevP;
    p.x+=0.13;
    p.y+=0.13;
    p*=Rot(radians(-135.));
    d2 = Tri(p,vec2(0.05));
    d = min(d,d2);    

    p = prevP;
    p.x-=0.13;
    p.y-=0.13;
    p*=Rot(radians(45.));
    d2 = Tri(p,vec2(0.05));
    d = min(d,d2);        

    return d;
}

float drawFont(vec2 p, int char){
    float d = 10.;
    if(char == 0) {
        d = char0(p);
    } else if(char == 2) {
        d = char2(p);
    } else if(char == 5) {
        d = char5(p);
    }

    return d;
}

float draw2025(vec2 p){
    vec2 prevP  = p;
    p.y-=iTime*0.1;
    p.y+=0.2;
    p.y = mod(p.y,0.4)-0.2;

    float d = drawFont(p-vec2(-0.42,0.0),2);
    float d2 = drawFont(p-vec2(-0.14,0.0),0);
    d = min(d,d2);
    d2 = drawFont(p-vec2(0.14,0.0),2);
    d = min(d,d2);
    d2 = drawFont(p-vec2(0.42,0.0),5);
    d = min(d,d2);

    p = prevP;
    d = max(abs(p.y)-0.19,d);
    return d;
}

float draw2025_copies(vec2 p){
    vec2 prevP = p;
    p.x = abs(p.x)-1.05;
    p.y = abs(p.y)-0.65;
    float d = draw2025(p*vec2(sign(prevP)));
    return d;
}

float midCenterItem(vec2 p){
    vec2 prevP = p;
    p.x=abs(p.x)-0.24;
    p*=Rot(radians(45.));

    float d = abs(Tri(p,vec2(0.1)))-0.01;
    p = prevP;
    p.y-=0.1;
    float d2 = abs(Tri(p,vec2(0.1)))-0.01;
    d = min(d,d2);

    return d;
}

float midCenterItems(vec2 p){
    vec2 prevP = p;
    p.y=abs(p.y)-0.24;
    float d = midCenterItem(p);
    p.y -=0.15;
    float d2 = midCenterItem(p);
    d = min(d,d2);

    p = prevP;
    p.x=abs(p.x)-0.24;
    p*=Rot(radians(90.));
    d2 = midCenterItem(p);
    d = min(d,d2);
    p.y -=0.15;
    d2 = midCenterItem(p);
    d = min(d,d2);
    return d;
}

float centerArrow(vec2 p){
    vec2 prevP = p;
    p.x = abs(p.x)-0.1;
    p*=Rot(radians(45.));
    float d = B(p,vec2(0.6,0.11));
    p = prevP;
    d = max(abs(p.x)-0.395,d);
    d = max(-(p.y+0.3),d);

    d = abs(d)-0.01;

    p.x = abs(p.x)-0.21;
    p.y-=0.05;
    p.x+=sin(iTime*2.)*0.1;
    p.y-=sin(iTime*2.)*0.1;
    p*=Rot(radians(45.));
    p.y = abs(p.y);
    p.y*=-1.0;

    float d2 = Tri(p,vec2(0.1));
    d = min(d,d2);

    return d;
}

float centerArrows(vec2 p){
    vec2 prevP = p;
    p.y=abs(p.y)-0.8;
    float d = centerArrow(p);
    p = prevP;
    p.x=abs(p.x)-0.8;
    p*=Rot(radians(90.));
    float d2 = centerArrow(p);
    d = min(d,d2);
    return d;
}

float centerRects(vec2 p){
    vec2 prevP = p;
    p = abs(p)-0.05;
    p*=Rot(radians(45.));
    float d = animateTri(p);
    p = prevP;
    p = abs(p)-0.18;
    p*=Rot(radians(-135.));
    float d2 = animateTri(p);
    d = min(d,d2);

    p = prevP;
    p.x = abs(p.x)-0.045;
    p.y = abs(p.y)-0.28;
    p*=Rot(radians(45.));
    d2 = Tri(p,vec2(0.02));
    d = min(d,d2);    

    p = prevP;
    p.x = abs(p.x)-0.28;
    p.y = abs(p.y)-0.045;
    p*=Rot(radians(45.));
    d2 = Tri(p,vec2(0.02));
    d = min(d,d2);       

    p = prevP;
    p = abs(p)-0.27;
    p*=Rot(radians(45.));
    d2 = animateTri(p);
    d = min(d,d2);   

    return d;
}

float outerItem(vec2 p){
    vec2 prevP = p;

    p.x = abs(p.x)-0.12;
    float d = B(p,vec2(0.075,0.005));
    p = prevP;
    p.x = abs(p.x)-0.105;
    p*=Rot(radians(-45.));
    float d2 = Tri(p,vec2(0.065));
    d = min(d,d2);

    p = prevP;
    p.x = abs(p.x)-0.055;
    p.y += 0.09;
    p*=Rot(radians(135.));
    d2 = Tri(p,vec2(0.065));
    d = min(d,d2);

    p = prevP;
    p.y -= 0.08;
    p.x = abs(p.x)-0.05;
    d2 = B(p,vec2(0.005,0.12));
    d = min(d,d2);

    p = prevP;
    p.y -= 0.2;
    p.x = abs(p.x)-0.05;
    p*=Rot(radians(-45.));
    d2 = Tri(p,vec2(0.065));
    d = min(d,d2);

    p = prevP;
    p.y -= 0.04;
    p.x = abs(p.x)-0.19;
    p*=Rot(radians(135.));
    d2 = abs(Tri(p,vec2(0.065)))-0.0045;
    p = prevP;
    d2 = max(-p.y+0.05,d2);
    d = min(d,d2);   

    p.x = abs(p.x)-0.11;
    d2 = B(p,vec2(0.005,0.051));
    d = min(d,d2);

    return d;
}

float animateOuterItem(vec2 p){
    vec2 prevP = p;

    p.y+=iTime*0.2;
    p.y+=0.15;
    p.y = mod(p.y,0.3)-0.15;

    float d = outerItem(p);
    p = prevP;
    p.y-=0.38;
    d = max(p.y-0.7,d);
    p = prevP;
    float a = radians(-45.);
    p.y += 0.1;
    p.x = abs(p.x)-0.17;
    d = max(dot(p,vec2(cos(a),sin(a))),d);

    return d;
}

float outerItems(vec2 p){
    vec2 prevP = p;
    p.y=abs(p.y)-0.7;
    float d = animateOuterItem(p);
    p = prevP;
    p.x=abs(p.x)-0.7;
    p*=Rot(radians(90.));
    float d2 = animateOuterItem(p);
    d = min(d,d2);
    return d;
}

float outerItem2(vec2 p){
    vec2 prevP = p;
    float d = abs(B(p,vec2(0.265,0.15)))-0.005;
    d = max(p.y-0.05,d);
    d = max(-(abs(p.x)-0.1),d);
    p.y*=-1.;
    p.y-=0.205;
    p.x = abs(p.x)-0.05;
    float d2 = abs(Tri(p,vec2(0.065)))-0.005;
    d2 = max(prevP.y+0.15,d2);
    d = min(d,d2);

    p = prevP;
    p.x+=0.05;
    p.y+=0.03;
    p*=Rot(radians(45.));
    d2 = B(p,vec2(0.05));
    d = min(d,d2);
    p.x-=0.1;
    p.y-=0.2;
    d2 = abs(B(p,vec2(0.05,0.15)))-0.005;
    d = min(d,d2);
    p = prevP;
    p.x+=0.19;
    p.y-=0.11;
    p*=Rot(radians(-45.));
    d2 = abs(B(p,vec2(0.045,0.15)))-0.005;
    d = min(d,d2);

    return d;
}

float outerItems2(vec2 p){
    vec2 prevP = p;

    p.x = abs(p.x)-0.48;
    p.y = abs(p.y)-0.48;
    p*=Rot(radians(-315.));
    float d = outerItem2(p);

    return d;
}

float CustomTri(vec2 p){
    vec2 prevP = p;
    p.y*=1.3;
    p*=Rot(radians(135.));

    float d = Tri(p,vec2(0.065));
    p = prevP;
    p.y-=0.005;
    float d2 = B(p,vec2(0.06,0.005));
    d = min(d,d2);
    return d;
}

float outerItem3(vec2 p){
    vec2 prevP = p;
    p.x+=iTime*0.15;
    p.x+=0.01;
    p.x = mod(p.x,0.16)-0.08;
    p.x-=0.03;
    float d = CustomTri(p);

    p = prevP;
    p.y-=0.38;
    d = max(abs(p.y)-0.5,d);
    p = prevP;
    float a = radians(-45.);
    p.y += 0.15;

    d = max(-dot(p,vec2(cos(a),sin(a))),d);

    return d;
}

float outerItems3(vec2 p){
    vec2 prevP = p;

    p.x = abs(p.x)-0.48;
    p.y = abs(p.y)-0.23;
    float d = outerItem3(p);

    p = prevP;
    p*=Rot(radians(90.));
    p.x = abs(p.x)-0.48;
    p.y = abs(p.y)-0.23;
    float d2 = outerItem3(p);
    d = min(d,d2);

    return d;
}

float outerItem4(vec2 p){
    vec2 prevP = p;
    p.x+=iTime*0.12;
    p.x+=0.02;
    p.x = mod(p.x,0.16)-0.08;
    p.x-=0.03;
    float d = B(p,vec2(0.05,0.02));
    p.x+=0.08;
    p.y*=1.3;
    p*=Rot(radians(-90.));
    float d2 = Tri(p,vec2(0.06));
    d = min(d,d2);

    p = prevP;
    p.x-=0.8;
    d = max(abs(p.x)-0.5,d);
    p = prevP;
    float a = radians(-45.);
    p.y += 0.15;

    d = max(-dot(p,vec2(cos(a),sin(a))),d);

    return d;
}

float outerItems4(vec2 p){
    vec2 prevP = p;

    p.x = abs(p.x)-0.48;
    p.y = abs(p.y)-0.395;
    float d = outerItem4(p);

    return d;
}

float render(vec2 p){
    vec2 prevP = p;

    float d = midCenterItems(p*2.);
    float d2 = centerArrows(p*2.);
    d = min(d,d2);
    d2 = centerRects(p);
    d = min(d,d2);
    d2 = outerItems(p);
    d = min(d,d2);

    d2 = outerItems2(p);
    d = min(d,d2);

    d2 = draw2025_copies(p);
    d2 = max(-(abs(p.y)-0.1),d2); // remove weird artifact when it's full screen...
    d = min(d,d2);

    d2 = outerItems3(p);
    d = min(d,d2);
    d2 = outerItems4(p);
    d = min(d,d2);

    return d;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (fragCoord-0.5*iResolution.xy)/iResolution.y;

    vec3 col = vec3(0.0);
    float d = render(p*2.);
    col = mix(col,vec3(1.),S(d));

    fragColor = vec4(col,1.0);
}
